import json

def load_json(p): 
    with open(p) as f: return json.load(f)
def load_jsonl(p):
    with open(p) as f: return [json.loads(l) for l in f if l.strip()]

estate = load_json('/opt/crypto-case/case/estate.json')
captured_at = estate['captured_at']

events = load_jsonl('/opt/crypto-case/case/deployment-events.jsonl')
events.sort(key=lambda x: x['time'])

active_subjects = {}
for ev in events:
    if ev['time'] > captured_at: continue
    subj = ev['subject']
    cons = ev['consumer']
    if ev['event'] == 'bind':
        active_subjects.setdefault(cons, set()).add(subj)
    elif ev['event'] == 'unbind':
        if cons in active_subjects and subj in active_subjects[cons]:
            active_subjects[cons].remove(subj)

obs = []
obs.extend(load_jsonl('/opt/crypto-case/case/tls-negotiations.jsonl'))
obs.extend(load_jsonl('/opt/crypto-case/case/signature-verifications.jsonl'))
obs.extend(load_jsonl('/opt/crypto-case/case/ssh-sessions.jsonl'))

valid_obs = [o for o in obs if o['result'] == 'success' and o['observed_at'] <= captured_at]
valid_obs.sort(key=lambda x: x['observed_at'], reverse=True)

deps = []
for cons_info in estate['consumers']:
    cons_id = cons_info['id']
    surface = cons_info['surface']
    if not cons_info.get('required'): continue
    if surface.startswith('archive:'): continue

    subjects = active_subjects.get(cons_id, set())
    cons_algs = set()
    cons_mats = set()
    cons_ev = set()

    for subj in subjects:
        for o in valid_obs:
            if o['surface'] == surface and o['subject'] == subj:
                cons_algs.update(o['algorithms'])
                cons_mats.update(o.get('materials', []))
                cons_ev.add(o['id'])
                break

    if cons_ev:
        deps.append({
            'surface': surface,
            'consumer': cons_id,
            'effective_algorithms': sorted(list(cons_algs)),
            'materials': sorted(list(cons_mats)),
            'evidence': sorted(list(cons_ev))
        })

archives = load_json('/opt/crypto-case/case/archives.json')
for arc in archives.get('archives', []):
    deps.append({
        'surface': arc['surface'],
        'consumer': arc['id'],
        'effective_algorithms': sorted([arc['data_cipher'], arc['wrap_algorithm']]),
        'materials': [arc['wrap_material']],
        'evidence': [arc['evidence']]
    })

incidents = load_json('/opt/crypto-case/case/incident-evidence.json')
compromised = set()
for inc in incidents.get('events', []):
    if inc.get('confidence') == 'confirmed':
        compromised.add(inc['material'])

materials = load_json('/opt/crypto-case/case/materials.json')
retire = set()
for mat_id, mat in materials.items():
    if mat.get('disposition') == 'retire_at_completion':
        retire.add(mat_id)

out = {
    'findings': {
        'compromised_material': sorted(list(compromised)),
        'retire_material': sorted(list(retire))
    },
    'dependencies': deps
}
print(json.dumps(out, indent=2))
EOF

